use super::*;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};

fn no_fields(_:usize)->Option<NativeRecordSchema>{None}
#[test]
fn original_matcher_frame_waits_for_its_funded_header_clear(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../📐️close.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));
 let mut owner=NativeRecordMatcher::<dyn NativeValueSource>::new(no_fields,0,NativeSchemaKeySource::Text);owner.pending=Some(SchemaFrame{fields:no_fields,count:0,index:0,root:None,role:0,before:NativeFieldMatch::Missing,best:NativeFieldMatch::Missing});let start=owner.begin_close_demand();let denied_start=bank.loan(1,0);let(poll,actual)=bank.run(denied_start,1,|effect|crate::RetainedWorkPoll::Complete(owner.begin_close_paid(effect)));let crate::RetainedWorkPoll::Complete(turn)=poll else{panic!("unstarted close-start denial remained pending")};assert_eq!(turn.work,0);assert!(!owner.close_started());assert_eq!(actual,None);assert_eq!(bank.take_admitted(),None);bank.post(RetainedCloneProgress::default(),denied_start,(0,0));let grant=bank.loan(1,start.copy_bytes);let(poll,actual)=bank.run(grant,1,|effect|crate::RetainedWorkPoll::Complete(owner.begin_close_paid(effect)));let crate::RetainedWorkPoll::Complete(turn)=poll else{panic!("funded matcher start remained pending")};assert_eq!(turn.work,u128::from(law["startWork"].as_u64().unwrap()));let progress=turn.result.unwrap().progress();assert!(owner.close_started());assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,(0,0));
 let demand=owner.close_demands(4096).unwrap();assert!(demand.copy_bytes>0);let denied=bank.loan(1,demand.copy_bytes-1);let(poll,actual)=bank.run(denied,1,|effect|owner.close_step(effect));let crate::RetainedWorkPoll::Complete(turn)=poll else{panic!("unstarted matcher denial remained pending")};assert_eq!(turn.work,u128::from(law["deniedWork"].as_u64().unwrap()));assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(law["denied"],"completedNoProgress");assert!(owner.pending.is_some());assert_eq!(actual,None);assert_eq!(bank.take_admitted(),None);bank.post(RetainedCloneProgress::default(),denied,(0,0));
 let grant=bank.loan(1,demand.copy_bytes);let(poll,actual)=bank.run(grant,1,|effect|owner.close_step(effect));let crate::RetainedWorkPoll::Complete(turn)=poll else{panic!("funded matcher clear remained pending")};assert_eq!(turn.work,u128::from(law["clearedWork"].as_u64().unwrap()));let progress=turn.result.unwrap().progress();assert_eq!(progress.copied_bytes,demand.copy_bytes);assert_eq!(law["cleared"],"backingFrame");assert!(owner.pending.is_none());assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,(0,0));assert!(owner.terminal_is_empty());
}
